mapper.select:
SELECT acs.id, acs.question_id AS questionId, q.title AS questionTitle, acs.title, acs.status, acs.is_delete AS isDelete, acs.create_time AS createTime, acs.update_time AS updateTime FROM ai_chat_session acs LEFT JOIN question q ON q.id = acs.question_id
acs.user_id = #{userId} AND acs.question_id = #{questionId} AND acs.is_delete = 0
AND acs.id < #{cursor}
ORDER BY acs.id DESC LIMIT #{limit}
